import { unstable_cache } from 'next/cache';

export interface Post {
  id: string;
  title: string;
}

// simulate a database
let posts: Post[] = [
  { id: '1', title: 'Initial Post' },
];

export const getPosts = unstable_cache(
  async () => {
    return posts;
  },
  ['posts-key'], // keyParts
  { tags: ['posts'] } // tags
);

export async function addPost(title: string) {
  // Simulate delay to make it realistic
  await new Promise(resolve => setTimeout(resolve, 100));
  posts.push({ id: Date.now().toString(), title });
}

'use server'

import { revalidateTag } from 'next/cache';
import { addPost } from './data';

export async function createPost(formData: FormData) {
  const title = formData.get('title');

  if (!title || typeof title !== 'string') {
    throw new Error('Title is required');
  }

  await addPost(title);

  // Invalidate the cache tag to ensure fresh data is fetched
  revalidateTag('posts');
}

